36fa82e4","en":"Building simple sentences","ru":"Построение простых предложений"},{"id":"b4dee624-58f7-4b1b-bbda-28817e95cd78","en":"Intonation Matching the Content of a Text","ru":"Интонация в соответствии с содержанием текста"},{"id":"33c78c01-8569-4e20-98a3-d462fbf6ba47","en":"Taking Part in Discussions","ru":"Участие в обсуждениях"},{"id":"06077a66-0676-4b03-b895-66d05d61122a","en":"Expressing Ideas in a Logical Order","ru":"Изложение мыслей в логической последовательности"},{"id":"98dbb86c-301c-4e08-8507-882f7f461301","en":"Reasoned Speech","ru":"Аргументированная речь"},{"id":"f8de7fcc-6e44-4ade-a103-9480db769907","en":"Responding to Differing Points of View","ru":"Отношение к различным точкам зрения"},{"id":"2aa015a2-ca58-4c1d-b3c6-49564c1d32d9","en":"Meaning of New Expressions and Terms","ru":"Значение новых выражений и терминов"},{"id":"4e484097-571c-4b09-bda2-20b6f89df8ea","en":"Distinguishing Texts of Different Styles","ru":"Различение текстов разных стилей"},{"id":"76f707c8-92e7-4d84-ad47-5f21ef09e5e1","en":"Meaning of New Expressions and Terms in Context","ru":"Значение новых выражений и терминов в контексте"},{"id":"c1d59289-f7d2-4341-9d23-bc06ba389f7a","en":"Reading Texts of Different Styles Correctly","ru":"Правильное чтение текстов разных стилей"},{"id":"d37efdb9-743c-4996-8c62-716b1a917f25","en":"Interpreting the Content of Texts","ru":"Толкование содержания текстов"},{"id":"109c4899-5c05-4125-8f6c-0335e82dc631","en":"Carrying Out Instructions in Sequence","ru":"Последовательное выполнение услышанных указаний"},{"id":"dcd4389f-94b2-4b96-96d7-8eea1554261b","en":"Grouping Facts and Events","ru":"Группировка фактов и событий"},{"id":"2cc6bdd5-5300-4204-af00-be2cba54b470","en":"Summarising","ru":"Обобщение"},{"id":"6708bb8a-909f-4bfc-96dc-216d226d8c26","en":"Interpreting Facts and Events","ru":"Толкование фактов и событий"},{"id":"23cbacd1-45c0-4629-9e98-b223e47dc42d","en":"Responding to Facts and Events","ru":"Отношение к фактам и событиям"},{"id":"f69887af-ad6b-40e3-8d69-243f222ac644","en":"Summarising Differing Points of View","ru":"Обобщение различных точек зрения"},{"id":"606b64e2-709b-43f0-aeb4-aab7d66dcdeb","en":"Dividing a Listening Text into Parts","ru":"Деление прослушанного текста на части"},{"id":"807475e9-66c5-4057-9da5-c44d80da022f","en":"Evaluating a Listening Text","ru":"Оценка прослушанного текста"},{"id":"cb09387f-7b9b-4c91-9de3-a39f8f49f8f1","en":"Expressing an Idea Through Different Sentence Structures","ru":"Выражение мысли разными синтаксическими конструкциями"},{"id":"20b235b9-55e7-4a5b-82dd-a37ac0e01334","en":"Explaining the Content of What Is Heard","ru":"Объяснение содержания прослушанной речи"},{"id":"3aac1528-5eee-4632-b14b-4205638df3f0","en":"Presentation Based on What Is Heard","ru":"Презентация на основе прослушанной информации"},{"id":"e7af5190-92d1-4ac9-bdcc-e71e02eda86f","en":"Selecting and Grouping Key Facts and Events","ru":"Выделение и группировка основных фактов и событий"},{"id":"1ba0f89a-195d-446e-9271-85157366372a","en":"Improving Your Own and Others'' Writing","ru":"Совершенствование собственного и чужого текста"},{"id":"3714e21c-0c25-4837-b211-e663df7183c4","en":"Analysing Facts and Events","ru":"Анализ фактов и событий"},{"id":"1eb9cc1e-4e84-4907-82cd-7b18bae61bf3","en":"Editing a Piece of Writing","ru":"Редактирование текста"},{"id":"fb648610-f9fc-4676-93c4-34a7172efea2","en":"Reasoning","ru":"Рассуждение"},{"id":"8c077ad5-1c94-4f74-a117-fee0cee2a31b","en":"Writing in Different Styles","ru":"Тексты разных стилей"},{"id":"e3aa407f-411c-4a75-83da-7737b8a26305","en":"Relating Facts and Events to Real Life","ru":"Связь фактов и событий с реальной жизнью"},{"id":"a87197d1-aba7-4f78-bdf3-b92cfec2772a","en":"Reading Sentences by Purpose and Intonation","ru":"Чтение предложений по цели высказывания и интонации"},{"id":"bccc7f3c-2d26-481f-9798-d81c172e3e51","en":"Making a Plan of a Text","ru":"Составление плана текста"},{"id":"e67a6cce-3d95-4205-8ffa-033da4332de5","en":"Informative Text","ru":"Информационный текст"},{"id":"5407bbe2-e0fc-48cc-8e04-2ad93f7c467b","en":"Filling In Forms","ru":"Заполнение анкет"},{"id":"3992c5a5-c3f0-4541-a1bb-073e2e5bd9d9","en":"Punctuation Marks","ru":"Знаки препинания"},{"id":"43377225-efb8-44f1-9daf-6714fa8157eb","en":"Linking Sentences and Paragraphs","ru":"Связь предложений и абзацев"},{"id":"38b7f56a-75fe-47c7-88ac-580cec2d3325","en":"Report","ru":"Отчёт"},{"id":"754c7d66-f12c-4556-80ee-2ddbebef4e6e","en":"Speech","ru":"Выступление"},{"id":"e7b813b1-5154-487b-9a7c-6e8168a0ea78","en":"Spelling, Grammar and Punctuation","ru":"Орфография, грамматика и пунктуация"},{"id":"baaace79-696c-4e3c-a6a8-2374fb88fb74","en":"Project","ru":"Проект"},{"id":"e772ed3b-d95d-4ed2-af68-0f56e40aa996","en":"Presentation","ru":"Презентация"}]'::jsonb;
  v_item    jsonb;
  v_n       int := 0;
  v_left    int;
begin
  for v_item in select * from jsonb_array_elements(v_payload)
  loop
    -- The subtopic must still exist. A row deleted between the export and this
    -- migration is skipped rather than resurrected.
    if exists (select 1 from public.subtopics st where st.id = (v_item->>'id')::uuid) then
      insert into public.subtopic_translations (subtopic_id, locale, name)
      values ((v_item->>'id')::uuid, 'en'::content_locale, v_item->>'en'),
             ((v_item->>'id')::uuid, 'ru'::content_locale, v_item->>'ru')
      on conflict (subtopic_id, locale)
        do update set name = excluded.name, updated_at = now();
      v_n := v_n + 1;
    end if;
  end loop;
  -- ASSERT ON WHAT THIS MIGRATION WROTE, not on the whole table.
  --
  -- The first run of this file failed here for a good reason and a bad rule: it
  -- demanded that NO subtopic anywhere was untranslated, and 39 new ones had
  -- been created by the content team in the two hours it took to translate the
  -- first 604. That is normal work, not a defect, and a migration that cannot
  -- succeed while people are using the product is a migration that never
  -- succeeds. The correct assertion is that every row this file TARGETED is
  -- now translated.
  select count(*) into v_left
  from jsonb_array_elements(v_payload) x
  join public.subtopics st on st.id = (x->>'id')::uuid
  where not exists (
    select 1 from public.subtopic_translations tr
    where tr.subtopic_id = st.id and tr.locale = 'en'
  );
  if v_left > 0 then
    raise exception '153: % targeted subtopic(s) did not receive a translation', v_left;
  end if;

  raise notice '153: translated % subtopic(s) into en + ru', v_n;
end $$;

-- -----------------------------------------------------------------------------
-- VERIFICATION. The number that has to reach zero.
-- -----------------------------------------------------------------------------
do $$
declare
  v_missing int;
  v_qs      int;
begin
  select count(*), coalesce(sum(q.n), 0)
    into v_missing, v_qs
  from public.subtopics st
  join public.topics t on t.id = st.topic_id and t.scope = 'exam'
  join lateral (select count(*) as n from public.questions q where q.subtopic_id = st.id) q on true
  where st.status <> 'archived'
    and not exists (
      select 1 from public.subtopic_translations x
      where x.subtopic_id = st.id and x.locale = 'en'
    );

  -- INFORMATIONAL, deliberately not an exception. Anything counted here was
  -- created after this file's payload was exported -- the content team adds
  -- subtopics daily, and each one starts untranslated by design (the admin
  -- creates it in Azerbaijani and translates in a later step). Migration 152's
  -- counter on the Curriculum page is where this number is meant to be watched.
  if v_missing > 0 then
    raise notice '153: % subtopic(s) created since the export are still untranslated, carrying % question(s) -- visible on the Curriculum page',
      v_missing, v_qs;
  else
    raise notice '153: every exam subtopic now has an English and a Russian name';
  end if;
end $$;

commit;
